long long pow10[12];

int digits(long long n) {
    if (n == 0) return 1;
    int d = 0;
    while (n > 0) {
        n /= 10;
        d++;
    }
    return d;
}

int main() {
    pow10[0] = 1;
    for (int i = 1; i < 12; i++) pow10[i] = pow10[i-1] * 10;

    long long A, B, P;
    while (1) {
        scanf("%lld %lld %lld", &A, &B, &P);
        if (A == 0 && B == 0 && P == 0) break;

        long long total = 0;

        int lenA = digits(A);
        int lenB = digits(B);

        for (int len = lenA; len <= lenB; len++) {
            long long low = (len == lenA) ? A : pow10[len-1];
            long long high = (len == lenB) ? B : pow10[len] - 1;
            if (low > high) continue;

            long long count = high - low + 1;
            // Number of non-empty subsets of this block: 2^count - 1 mod P
            long long pow2 = 1;
            long long c = count;
            long long mod = P;
            long long base = 2;
            while (c > 0) {
                if (c & 1) pow2 = (pow2 * base) % mod;
                base = (base * base) % mod;
                c >>= 1;
            }
            pow2 = (pow2 - 1 + mod) % mod;
            total = (total + pow2) % mod;
        }

        printf("%lld\n", total);
    }
    return 0;
}

