struct Fenwick {
    int n;
    vector<int64> bit;
    Fenwick(int n) : n(n), bit(n+1, 0) {}
    void add(int idx, int64 val, int64 mod) {
        for (++idx; idx <= n; idx += idx & -idx)
            bit[idx] = (bit[idx] + val) % mod;
    }
    int64 sum(int idx, int64 mod) {
        int64 res = 0;
        for (++idx; idx > 0; idx -= idx & -idx)
            res = (res + bit[idx]) % mod;
        return res;
    }
};

