#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

static const int MAXL = 20; // enough for 64-bit integers

struct TrieNode {
    int ch[10];
    bool term;
    TrieNode() {
        memset(ch, -1, sizeof(ch));
        term = false;
    }
};

static vector<TrieNode> trie;
static long long MOD;

// insert decimal string into trie
void insert_str(const string& s) {
    int u = 0;
    for (char c : s) {
        int d = c - '0';
        if (trie[u].ch[d] == -1) {
            trie[u].ch[d] = (int)trie.size();
            trie.emplace_back();
        }
        u = trie[u].ch[d];
    }
    trie[u].term = true;
}

// DP on trie:
// f(u) = number of valid subsets of terminal numbers in subtree rooted at u,
// including empty subset, such that lexicographic and numeric order coincide.
long long dfs(int u) {
    // If a number ends here, then any chosen number below would have this number as prefix,
    // causing lexicographic order to differ from numeric order if both are selected.
    // So if term=true, we may either:
    //   - choose this number alone from this subtree
    //   - choose nothing
    // and cannot combine with descendants.
    if (trie[u].term) return 2 % MOD;

    long long res = 1 % MOD;
    for (int d = 0; d < 10; ++d) {
        int v = trie[u].ch[d];
        if (v != -1) {
            res = (res * dfs(v)) % MOD;
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long A, B, P;
    while (cin >> A >> B >> P) {
        if (A == 0 && B == 0 && P == 0) break;
        MOD = P;

        trie.clear();
        trie.emplace_back(); // root

        for (long long x = A; x <= B; ++x) {
            insert_str(to_string(x));
            if (x == B) break; // avoid overflow if B = LLONG_MAX
        }

        long long ans = dfs(0) - 1; // exclude empty subset
        ans %= MOD;
        if (ans < 0) ans += MOD;
        cout << ans % MOD << '\n';
    }
    return 0;
}

