import sys

def count_subsets(A, B, P):
    total = 0
    mod = P
    # iterate over possible digit lengths
    length = 1
    while True:
        start = 10 ** (length - 1)
        end = 10 ** length - 1
        if start > B:
            break
        seg_start = max(start, A)
        seg_end = min(end, B)
        if seg_start <= seg_end:
            k = seg_end - seg_start + 1
            total = (total + pow(2, k, mod) - 1) % mod
        length += 1
    return total % mod

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        A, B, P = map(int, line.split())
        if A == 0 and B == 0 and P == 0:
            break
        print(count_subsets(A, B, P))

